public class Parser {
    private int parseEndOfLine(String headerPart, int end) {
        int i = end;
        while (i < headerPart.length() && headerPart.charAt(i) != '\r' && headerPart.charAt(i) != '\n') {
            i++;
        }
        if (i == headerPart.length()) {
            throw new IOException("End of line not found");
        }
        if (headerPart.charAt(i) == '\r' && i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
            i++;
        }
        return i;
    }

    public static void main(String[] args) {
        Parser parser = new Parser();
        try {
