public class GraphUtils {

    /** 
     * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
     * @param graph the input graph
     * @param < V > the graph vertex type
     * @param < E > the graph edge type
     * @return a mapping from graph to graph
     */
    public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
        Map<V, V> identityMap = new HashMap<>();
        for (V vertex : graph.getVertices()) {
            identityMap.put(vertex, vertex);
        }
        return new IsomorphicGraphMapping<>(graph, identityMap);
    }

    public static void main(String[] args) {
        // Example usage
        Graph<String, String> graph = new SimpleGraph<>();
        graph.addVertex("A");
        graph.addVertex("B");
        graph.addEdge("A", "B");

        IsomorphicGraphMapping<String, String> identityMapping = identity(graph);
        System.out.println(identityMapping);
    }
}

