public class LoggingBuffer {
    private Logger LOG = Logger.getLogger(LoggingBuffer.class.getName());
    private LoggingEvent[] buffer;
    private int head;
    private int tail;
    private int size;

    public LoggingBuffer(int capacity) {
        buffer = new LoggingEvent[capacity];
        head = 0;
        tail = 0;
        size = 0;
    }

    public void put(LoggingEvent o) {
        if (size == buffer.length) {
            LOG.warning("Buffer is full, event silently dropped.");
            return;
        }
        buffer[tail] = o;
        tail = (tail + 1) % buffer.length;
        size++;
    }
}

