    private int size;

    public ByteVector() {
        this.data = new byte[16];
        this.size = 0;
    }

    public ByteVector(int initialCapacity) {
        this.data = new byte[initialCapacity];
        this.size = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            for (int i = 0; i < byteLength; i++) {
                putByte((byte) 0);
            }
        } else {
            if (byteOffset + byteLength > byteArrayValue.length) {
                throw new IllegalArgumentException("byteOffset + byteLength exceeds the length of byteArrayValue");
            }
            for (int i = 0; i < byteLength; i++) {
                putByte(byteArrayValue[byteOffset + i]);
            }
        }
        return this;
    }

    private void putByte(byte b) {
        if (size == data.length) {
            grow();
        }
        data[size++] = b;
    }

    private void grow() {
        int newCapacity = data.length * 2;
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }

    // Other methods like getByte, getSize, etc. can be added here
}

