import java.util.regex.Pattern;

public class StringUnescape {

    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        // Regular expression to match Java escape sequences
        Pattern pattern = Pattern.compile("\\\\(\\\\|n|r|t|b|f|u[0-9A-Fa-f]{4}|x[0-9A-Fa-f]{2})");
        Matcher matcher = pattern.matcher(str);

        // StringBuilder to build the unescaped string
        StringBuilder result = new StringBuilder();

        int lastEnd = 0;
        while (matcher.find()) {
            // Append the part of the string before the match
            result.append(str.substring(lastEnd, matcher.start()));

            // Handle different escape sequences
            String escapeSequence = matcher.group(1);
            switch (escapeSequence) {
                case "\\\\":
                    result.append("\\");
                    break;
                case "n":
                    result.append("\n");
                    break;
                case "r":
                    result.append("\r");
                    break;
                case "t":
                    result.append("\t");
                    break;
                case "b":
                    result.append("\b");
                    break;
                case "f":
                    result.append("\f");
                    break;
                case "u":
                    // Parse Unicode escape sequence
                    String unicode = matcher.group(2);
                    result.append((char) Integer.parseInt(unicode, 16));
                    break;
                case "x":
                    // Parse hexadecimal escape sequence
                    String hex = matcher.group(2);
                    result.append((char) Integer.parseInt(hex, 16));
                    break;
                default:
                    throw new IllegalArgumentException("Unknown escape sequence: " + escapeSequence);
            }

            // Move the last end to the end of the current match
            lastEnd = matcher.end();
        }

        // Append the remaining part of the string after the last match
        result.append(str.substring(lastEnd));

        return result.toString();
    }

    public static void main(String[] args) {
        try {
            String input = "This is a test string with escape sequences: \\n, \\r, \\t, \\b, \\f, \\u0041, \\x41.";
            String output = unescapeJava(input);
            System.out.println(output);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
