public class LogCalculator {

    /** 
     * Computes floor($\log_2 (n)$) $+ 1$
     */
    private int computeBinaryLog(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }
        int log = 0;
        while (n > 1) {
            n >>= 1;
            log++;
        }
        return log + 1;
    }

    public static void main(String[] args) {
        LogCalculator calculator = new LogCalculator();
        System.out.println(calculator.computeBinaryLog(16)); // Output: 4
        System.out.println(calculator.computeBinaryLog(1));  // Output: 1
        System.out.println(calculator.computeBinaryLog(2));  // Output: 2
    }
}

