import java.util.Scanner;

public class TokenParser {
    private String parseToken(final char[] terminators) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder token = new StringBuilder();
        while (scanner.hasNext()) {
            String input = scanner.next();
            if (input.isEmpty()) {
                continue;
            }
            for (char c : input.toCharArray()) {
                if (isTerminator(c, terminators)) {
                    break;
                }
                token.append(c);
            }
            if (isTerminator(token.charAt(token.length() - 1), terminators)) {
                break;
            }
        }
        scanner.close();
        return token.toString();
    }

    private boolean isTerminator(char c, char[] terminators) {
        for (char terminator : terminators) {
            if (c == terminator) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        TokenParser parser = new TokenParser();
        char[] terminators = {' ', ',', '.', '!'};
        String token = parser.parseToken(terminators);
        System.out.println("Parsed token: " + token);
    }
}

