import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TemplateEncoder {

    /** 
     * Encodes a string with template parameters names present, specifically the characters '{' and '}' will be percent-encoded.
     * @param s the string with zero or more template parameters names
     * @return the string with encoded template parameters names.
     */
    public static String encodeTemplateNames(String s) {
        if (s == null) {
            return null;
        }
        Pattern pattern = Pattern.compile("\\{([^}]+)\\}");
        Matcher matcher = pattern.matcher(s);
        StringBuffer encoded = new StringBuffer();
        while (matcher.find()) {
            matcher.appendReplacement(encoded, "%" + matcher.group(1).replace("%", "%25"));
        }
        matcher.appendTail(encoded);
        return encoded.toString();
    }

    public static void main(String[] args) {
        String input = "Hello {name}! Welcome to {world}.";
        String encoded = encodeTemplateNames(input);
        System.out.println(encoded);  // Output: Hello %7Bname%7D! Welcome to %7Bworld%7D.
    }
}

import java.awt.geom.Point2D;

public class Point2DUtils {

    /** 
     * Compare two points for equality using tolerance 1e-9.
     * @param p1 the first point
     * @param p2 the second point
     * @return whether the two points are equal or not
     */
    public static boolean equals(Point2D p1, Point2D p2) {
        if (p1 == null || p2 == null) {
            return p1 == p2;
        }
        return Math.abs(p1.getX() - p2.getX()) < 1e-9 && Math.abs(p1.getY() - p2.getY()) < 1e-9;
    }

    public static void main(String[] args) {
        Point2D p1 = new Point2D.Double(1.0, 2.0);
        Point2D p2 = new Point2D.Double(1.000000001, 2.0);
        System.out.println(equals(p1, p2)); // true
    }
}

