import java.util.Arrays;

public class ArrayUtils {
    /** 
     * Returns a new array of Strings without null elements. Internal method used to normalize exclude lists (arrays and collections). Note that  {@link Arrays#sort(Object[])} will throw an {@link NullPointerException}if an array element is <code>null</code>.
     * @param array The array to check
     * @return The given array or a new array without null.
     */
    static String[] toNoNullStringArray(Object[] array) {
        if (array == null) {
            return new String[0];
        }
        int nonNullCount = 0;
        for (Object element : array) {
            if (element != null) {
                nonNullCount++;
            }
        }
        String[] result = new String[nonNullCount];
        int index = 0;
        for (Object element : array) {
            if (element != null) {
                result[index++] = element.toString();
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Object[] array = {"a", null, "b", null, "c"};
        String[] result = toNoNullStringArray(array);
        System.out.println(Arrays.toString(result)); // Output: [a, b, c]
    }
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastSeparatorIndex = filename.lastIndexOf('/');
    if (lastSeparatorIndex == -1) {
        lastSeparatorIndex = filename.lastIndexOf('\\');
    }
    if (lastSeparatorIndex == -1) {
        return filename.lastIndexOf('.');
    }
    int extensionIndex = filename.lastIndexOf('.', lastSeparatorIndex);
    if (extensionIndex == -1 || extensionIndex == lastSeparatorIndex) {
        return -1;
    }
    return extensionIndex;
}

