public class Graph {
    private Map<String, Node> nodes;
    private Map<Node, List<Edge>> edges;

    public Graph() {
        nodes = new HashMap<>();
        edges = new HashMap<>();
    }

    public void addNode(String name) {
        Node node = new Node(name);
        nodes.put(name, node);
    }

    public void addEdge(String from, String to) {
        Node fromNode = nodes.get(from);
        Node toNode = nodes.get(to);
        if (fromNode == null || toNode == null) {
            throw new IllegalArgumentException("Node not found");
        }
        Edge edge = new Edge(fromNode, toNode);
        edges.computeIfAbsent(fromNode, k -> new ArrayList<>()).add(edge);
    }

    public Edge edgeToNext(String currentNode) {
        List<Edge> outgoingEdges = edges.get(nodes.get(currentNode));
        if (outgoingEdges == null || outgoingEdges.isEmpty()) {
            throw new IllegalArgumentException("No outgoing edges from the current node");
        }
        return outgoingEdges.get(0);
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int strLength = str.length();
    int subLength = substring.length();
    if (index < 0 || index + subLength > strLength) {
        return false;
    }
    for (int i = 0; i < subLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

